cat << 'EOF' > src/types/messages.test.ts
import type {
  IncomingMessage,
  OutgoingMessage,
  ListSessionsMessage,
  SessionListMessage,
  SessionSummaryFrame,
} from './messages.js';

describe('messages types', () => {
  it('pins that every message literal valid before this change still compiles', () => {
    const incoming: IncomingMessage[] = [
      { type: 'user_message', content: 'hello' },
      { type: 'ping', timestamp: 123 },
    ];
    const outgoing: OutgoingMessage[] = [
      { type: 'connected', sessionId: 's1', message: 'hi', examplePrompts: [] },
      { type: 'pong', timestamp: 123 },
      { type: 'stream_end' },
    ];
    expect(incoming).toBeDefined();
    expect(outgoing).toBeDefined();
  });

  it('allows the new list_sessions and session_list frames', () => {
    const listSessions: ListSessionsMessage = { 
      type: 'list_sessions', 
      limit: 10, 
      before: { sessionId: 's1', updatedAt: '2026-01-01T00:00:00.000Z' } 
    };
    const incomingWithNew: IncomingMessage = listSessions;

    const summary: SessionSummaryFrame = {
      sessionId: 's1',
      createdAt: '2026-01-01T00:00:00.000Z',
      updatedAt: '2026-01-01T00:00:00.000Z',
      entryCount: 1,
    };

    const sessionList: SessionListMessage = {
      type: 'session_list',
      sessions: [summary],
    };
    const outgoingWithNew: OutgoingMessage = sessionList;

    expect(incomingWithNew.type).toBe('list_sessions');
    expect(outgoingWithNew.type).toBe('session_list');
  });
});
EOF
npx vitest run src/types/messages.test.ts

